        const col = new T3.Mesh(new T3.CylinderGeometry(0.105, 0.13, 0.07, 40), mkMat(0xe9edf2, 0.1, 0.45)); col.rotation.x = Math.PI / 2; col.position.z = 0.065; b.add(plate, col);
