        const mk = () => new T3.Mesh(new T3.BoxGeometry(w, 1, w), mkMat(mat.color, mat.metal, mat.rough));
        this.lm.push(reg(mk(), { kind: 'link', i })); this.xm.push(reg(mk(), { kind: 'link', i }));
