    /** gripping point: TCP frame origin advanced along its z by the tool length */
    gripPoint() { const Tn = this.tcpT(); const z = [Tn[0][2], Tn[1][2], Tn[2][2]]; return M.v3.add(M.pof(Tn), M.v3.scale(z, this.toolLen())); }
