      mkBin('end', [endX, c.convY], 0x0a7ea4, 'Conveyor bin'); mkBin('A', [0.05, -0.62], 0xe5484d, 'Bin A · red / accept'); mkBin('B', [0.42, -0.62], 0x1f6feb, 'Bin B · blue / reject');
