    function footprint() { const hgt = cell.camH - 0.045 - cell.tableH; const hx = hgt * Math.tan(25 * M.D2R), hy = hgt * Math.tan(19 * M.D2R); return { hx, hy, mmpx: 2 * hx / cell.camRes * 1000 }; }
